<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/lms_v1360.php';sk1360_require_login();$id=(int)($_GET['id']??$_POST['course_id']??0);$e=sk1360_enrollment($id,sk1360_uid());if(!$e||!in_array($e['status'],['active','completed'],true)){http_response_code(403);exit('Active enrollment required.');}$c=sk1360_course($id);$msg='';$err='';try{$msg=sk1360_post_action('student');$e=sk1360_enrollment($id,sk1360_uid())?:$e;}catch(Throwable $x){$err=$x->getMessage();}$pdo=sk1360_db();$tid=sk1360_tid();$csrf=sk1360_csrf();$sections=sk1360_course_sections($id,true);$q=$pdo->prepare('SELECT lesson_id FROM lms_lesson_progress_v1360 WHERE tenant_id=? AND enrollment_id=? AND status=\'completed\'');$q->execute([$tid,$e['id']]);$done=array_fill_keys(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)?:[]),true);$q=$pdo->prepare("SELECT * FROM lms_assignments_v1360 WHERE tenant_id=? AND course_id=? AND status='published' ORDER BY due_at,id");$q->execute([$tid,$id]);$assignments=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$q=$pdo->prepare("SELECT * FROM lms_quizzes_v1360 WHERE tenant_id=? AND course_id=? AND status='published' ORDER BY id");$q->execute([$tid,$id]);$quizzes=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$student=sk1360_student();$q=$pdo->prepare("SELECT * FROM lms_announcements_v1360 WHERE tenant_id=? AND course_id=? AND status='published' AND audience IN('all','students') ORDER BY published_at DESC LIMIT 30");$q->execute([$tid,$id]);$ann=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$cert=null;if($e['status']==='completed'){$q=$pdo->prepare('SELECT * FROM lms_certificates_v1360 WHERE tenant_id=? AND enrollment_id=? LIMIT 1');$q->execute([$tid,$e['id']]);$cert=$q->fetch(PDO::FETCH_ASSOC)?:null;}sk1360_lms_shell($c['title'],'student');?><section class="portal-hero"><div><a href="/student/lms.php" class="back">← My Learning</a><span class="eyebrow"><?=sk1360_h($c['code'])?> · <?=sk1360_h($c['category'])?></span><h1><?=sk1360_h($c['title'])?></h1><p><?=sk1360_h($c['summary'])?></p></div><div class="course-progress"><b><?=$e['progress_percent']?>%</b><span>complete</span></div></section><?php if($msg):?><div class="lms-alert ok"><?=sk1360_h($msg)?></div><?php endif;?><?php if($err):?><div class="lms-alert err"><?=sk1360_h($err)?></div><?php endif;?><?php if($cert):?><div class="certificate-banner"><b>✓ Course Completed</b><span>Certificate <?=sk1360_h($cert['certificate_no'])?> issued <?=sk1360_h($cert['issued_at'])?></span></div><?php endif;?>
<div class="learning-layout"><section><h2>Curriculum</h2><div class="curriculum student"><?php foreach($sections as $s):?><article><h3><?=sk1360_h($s['title'])?><small><?=count($s['lessons'])?> lessons</small></h3><?php foreach($s['lessons'] as $l):?><details class="lesson-detail" <?=$l['is_preview']?'open':''?>><summary><span class="lesson-check <?=isset($done[$l['id']])?'done':''?>"><?=isset($done[$l['id']])?'✓':'○'?></span><b><?=sk1360_h($l['title'])?></b><small><?=sk1360_h($l['lesson_type'])?> · <?=$l['duration_minutes']?> min</small></summary><div class="lesson-body"><p><?=nl2br(sk1360_h($l['content']))?></p><?php if($l['resource_url']):?><a class="btn secondary" href="<?=sk1360_h($l['resource_url'])?>" target="_blank" rel="noopener">Open Resource</a><?php endif;?><?php if(!isset($done[$l['id']])&&$e['status']==='active'):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1360_h($csrf)?>"><input type="hidden" name="action" value="lesson.complete"><input type="hidden" name="course_id" value="<?=$id?>"><input type="hidden" name="lesson_id" value="<?=$l['id']?>"><button>Mark Lesson Complete</button></form><?php endif;?></div></details><?php endforeach;?></article><?php endforeach;?></div></section><aside><section class="portal-panel"><h2>Announcements</h2><?php foreach($ann as $a):?><article class="announcement"><b><?=sk1360_h($a['title'])?></b><small><?=sk1360_h($a['published_at'])?></small><p><?=nl2br(sk1360_h($a['body']))?></p></article><?php endforeach;?></section></aside></div>
<section class="portal-panel"><h2>Assignments</h2><div class="assessment-grid"><?php foreach($assignments as $a):$sq=$pdo->prepare('SELECT * FROM lms_assignment_submissions_v1360 WHERE tenant_id=? AND assignment_id=? AND student_id=? LIMIT 1');$sq->execute([$tid,$a['id'],$student['id']]);$sub=$sq->fetch(PDO::FETCH_ASSOC)?:null;?><article><h3><?=sk1360_h($a['title'])?></h3><p><?=nl2br(sk1360_h($a['instructions']))?></p><small>Max <?=$a['max_score']?> · Due <?=sk1360_h($a['due_at']?:'Any time')?></small><?php if($sub):?><div class="submission-status"><b><?=sk1360_h($sub['status'])?></b><?php if($sub['status']==='graded'):?><span>Score: <?=sk1360_h($sub['score'])?></span><p><?=sk1360_h($sub['feedback'])?></p><?php endif;?></div><?php endif;?><?php if($e['status']==='active'):?><form method="post" class="lms-form"><input type="hidden" name="_csrf" value="<?=sk1360_h($csrf)?>"><input type="hidden" name="action" value="assignment.submit"><input type="hidden" name="course_id" value="<?=$id?>"><input type="hidden" name="assignment_id" value="<?=$a['id']?>"><label>Your Submission<textarea name="body" rows="4" required><?=sk1360_h($sub['body']??'')?></textarea></label><button>Submit Assignment</button></form><?php endif;?></article><?php endforeach;?></div></section>
<section class="portal-panel"><h2>Quizzes</h2><div class="assessment-grid"><?php foreach($quizzes as $qz):$qq=$pdo->prepare('SELECT * FROM lms_quiz_questions_v1360 WHERE tenant_id=? AND quiz_id=? ORDER BY sort_order,id');$qq->execute([$tid,$qz['id']]);$qs=$qq->fetchAll(PDO::FETCH_ASSOC)?:[];$aq=$pdo->prepare('SELECT * FROM lms_quiz_attempts_v1360 WHERE tenant_id=? AND quiz_id=? AND student_id=? ORDER BY id DESC LIMIT 1');$aq->execute([$tid,$qz['id'],$student['id']]);$last=$aq->fetch(PDO::FETCH_ASSOC)?:null;?><article><h3><?=sk1360_h($qz['title'])?></h3><p><?=sk1360_h($qz['instructions'])?></p><?php if($last):?><div class="submission-status"><b>Latest: <?=$last['percent']?>%</b><span><?=((float)$last['percent']>=(float)$qz['pass_percent'])?'Passed':'Needs improvement'?></span></div><?php endif;?><?php if($e['status']==='active'&&$qs):?><form method="post" class="quiz-form"><input type="hidden" name="_csrf" value="<?=sk1360_h($csrf)?>"><input type="hidden" name="action" value="quiz.submit"><input type="hidden" name="course_id" value="<?=$id?>"><input type="hidden" name="quiz_id" value="<?=$qz['id']?>"><?php foreach($qs as $n=>$qqq):$opts=json_decode((string)$qqq['options_json'],true)?:[];?><fieldset><legend><?=($n+1)?>. <?=sk1360_h($qqq['question_text'])?></legend><?php foreach($opts as $key=>$val):?><label><input type="radio" name="q_<?=$qqq['id']?>" value="<?=sk1360_h($key)?>" required> <?=sk1360_h($val)?></label><?php endforeach;?></fieldset><?php endforeach;?><button>Submit Quiz</button></form><?php endif;?></article><?php endforeach;?></div></section><?php sk1360_lms_end();
